"use client";

import { useCallback,useEffect,useMemo,useState } from "react";
import Link from "next/link";
import ThemeControl from "@/components/ThemeControl";
import { CREDIT_DISCLAIMER } from "@/lib/credits";
import { createAuthClient } from "@neon/auth/next";
import { usePathname,useRouter } from "next/navigation";
import { motion } from "motion/react";
import { Activity,ArrowDownLeft,ArrowLeftRight,ArrowRight,ArrowUpRight,Award,BookOpen,Brain,BriefcaseBusiness,Check,CheckCheck,CheckCircle2,ChevronDown,Clock3,Compass,Crown,Eye,GraduationCap,HandHeart,LayoutDashboard,Lightbulb,LogOut,Medal,Menu,MessageSquareText,Plus,Search,Settings,ShieldCheck,SlidersHorizontal,Sparkles,Star,Tags,Trash2,Trophy,Users,UserRound,X,Bell } from "lucide-react";

const titleMap={"/dashboard":"Dashboard","/credits":"SkillSwap Credits","/leaderboard":"Student Leaderboard","/pending":"Account review","/explore":"Explore skills","/my-skills":"My skills","/swap-requests":"Swap requests","/my-exchanges":"My exchanges","/notifications":"Notifications","/profile":"My profile","/settings":"Settings","/admin":"Admin dashboard","/admin/credits":"Credit management","/admin/users":"Student management","/admin/skills":"Skill management","/admin/categories":"Categories","/admin/swaps":"Swap activity"};
const studentNav=[["/dashboard","Dashboard",LayoutDashboard],["/explore","Explore skills",Compass],["/credits","SkillSwap Credits",Sparkles],["/leaderboard","Leaderboard",Users],["/my-skills","My skills",BookOpen],["/swap-requests","Swap requests",ArrowLeftRight],["/my-exchanges","My exchanges",Activity],["/notifications","Notifications",Bell],["/profile","My profile",UserRound],["/settings","Settings",Settings]];
const adminNav=[["/admin","Overview",LayoutDashboard],["/admin/users","Students",Users],["/admin/credits","Credits",Sparkles],["/admin/skills","Skills",BookOpen],["/admin/categories","Categories",Tags],["/admin/swaps","Swap activity",Activity],["/notifications","Notifications",Bell],["/settings","Settings",Settings]];
const request=async(url,method="GET",body)=>{const r=await fetch(url,{method,cache:"no-store",headers:body?{"Content-Type":"application/json"}:{},body:body?JSON.stringify(body):undefined});const out=await r.json().catch(()=>({}));if(!r.ok)throw new Error(out.error||"Something went wrong.");return out;};
const authClient=createAuthClient();
const nice=(s="")=>s.charAt(0).toUpperCase()+s.slice(1);
const initials=(s="Student")=>s.split(/\s+/).map(v=>v[0]).slice(0,2).join("").toUpperCase();
function Empty({icon:Icon=Sparkles,title,copy,action}){return <div className="empty-state"><span className="empty-icon"><Icon size={21}/></span><h3>{title}</h3><p>{copy}</p>{action}</div>}
function Status({value}){return <span className={`status-pill ${String(value).toLowerCase()}`}>{nice(value)}</span>}

export default function PortalScreen({studentId}){
 const path=usePathname(),router=useRouter(),[me,setMe]=useState(null),[data,setData]=useState({}),[loading,setLoading]=useState(true),[error,setError]=useState(""),[notice,setNotice]=useState(""),[mobile,setMobile]=useState(false),[filter,setFilter]=useState({q:"",category:"",level:"",department:"",year:"",rating:""}),[tab,setTab]=useState("all"),[modal,setModal]=useState(null),[busy,setBusy]=useState(false),[leaderboardScope,setLeaderboardScope]=useState("real"),[leaderboardFilter,setLeaderboardFilter]=useState("overall"),[leaderboardDepartment,setLeaderboardDepartment]=useState(""),[adminCreditScope,setAdminCreditScope]=useState("all");
 const isAdmin=me?.role==="admin",limited=me?.role==="student"&&["pending","rejected"].includes(me.account_status),nav=isAdmin?adminNav:limited?[["/pending","Account status",ShieldCheck],["/explore","Explore skills",Compass],["/profile","My profile",UserRound],["/notifications","Notifications",Bell],["/settings","Settings",Settings]]:studentNav,title=path.startsWith("/students/")?"Student profile":titleMap[path]||"SkillSwap";
 const load=useCallback(async()=>{
  setLoading(true);setError("");try{const {user}=await request("/api/auth/me");setMe(user);
   if(user.role==="admin"){
    if(path==="/admin"){const [a,u]=await Promise.all([request("/api/admin/dashboard"),request("/api/admin/users?status=pending")]);setData({...a,pendingUsers:u.users});}
    else if(path==="/notifications")setData(await request("/api/notifications"));
    else if(path==="/admin/credits")setData(await request(`/api/admin/credits?scope=${adminCreditScope}`));
    else if(path==="/admin/users")setData(await request("/api/admin/users"));
    else if(path==="/admin/skills")setData(await request("/api/admin/skills"));
    else if(path==="/admin/categories")setData(await request("/api/admin/categories"));
    else if(path==="/admin/swaps")setData(await request("/api/admin/swaps"));
   }else if(path==="/dashboard"){const [a,p,c]=await Promise.all([request("/api/dashboard"),request("/api/profile"),request("/api/credits")]);setData({...a,profile:p.profile,credits:c});}
   else if(path==="/pending"){const [a,p,c]=await Promise.all([request("/api/dashboard"),request("/api/profile"),request("/api/support")]);setData({...a,profile:p.profile,contactEmail:c.contactEmail});}
   else if(path==="/credits")setData(await request("/api/credits"));
   else if(path==="/leaderboard")setData(await request(`/api/leaderboard?scope=${leaderboardScope}&filter=${leaderboardFilter}&department=${encodeURIComponent(leaderboardDepartment)}`));
   else if(path==="/explore"){const [a,b]=await Promise.all([request(`/api/skills?${new URLSearchParams(Object.entries(filter).filter(([,v])=>v))}`),request("/api/swaps")]);setData({...a,mySkills:b.mySkills});}
   else if(path==="/my-skills"){const [a,b]=await Promise.all([request("/api/skills/mine"),request("/api/categories")]);setData({...a,...b});}
   else if(path==="/swap-requests"||path==="/my-exchanges")setData(await request("/api/swaps"));
   else if(path==="/notifications")setData(await request("/api/notifications"));
   else if(path==="/profile"){const [a,b,c]=await Promise.all([request("/api/profile"),request("/api/reviews"),request("/api/credits")]);setData({...a,...b,credits:c});}
   else if(studentId)setData(await request(`/api/students/${studentId}`));
  }catch(e){if(e.message==="Not signed in.")router.replace("/");else setError(e.message);}finally{setLoading(false);}
 },[path,router,filter,studentId,leaderboardScope,leaderboardFilter,leaderboardDepartment,adminCreditScope]);
 // Start an async fetch when the route or search filters change.
 // eslint-disable-next-line react-hooks/set-state-in-effect
 useEffect(()=>{load();},[load]);
 useEffect(()=>{if(me?.role==="admin"&&!path.startsWith("/admin")&&!["/notifications","/settings"].includes(path))router.replace("/admin");if(me?.role==="student"&&path.startsWith("/admin"))router.replace(me.account_status==="approved"?"/dashboard":"/pending");if(me?.role==="student"&&me.account_status==="pending"&&!(["/pending","/explore","/profile","/notifications","/settings"].includes(path)))router.replace("/pending");if(me?.role==="student"&&me.account_status==="rejected"&&!(["/pending","/profile","/settings"].includes(path)))router.replace("/pending");},[me,path,router]);
 async function act(url,method="POST",body,success="Saved."){setBusy(true);setError("");setNotice("");try{await request(url,method,body);setNotice(success);setModal(null);await load();return true;}catch(e){setError(e.message);return false;}finally{setBusy(false);}}
 async function loadMoreCredits(){const offset=data.activity?.length||0;const next=await request(`/api/credits?offset=${offset}`);setData(current=>({...current,activity:[...(current.activity||[]),...next.activity],pagination:next.pagination}));}
 async function logout(){try{await authClient.signOut();setMe(null);setData({});router.replace("/");}catch(e){setError(e.message||"Could not end the current session.");}}
 const unread=data.unreadCount||0;
 return <div className="app-shell">
  <aside className={`sidebar ${mobile?"open":""}`}><Link href={isAdmin?"/admin":"/dashboard"} className="brand"><span className="brand-mark"><ArrowLeftRight size={22}/></span><b>SkillSwap</b></Link><div className="side-label">{isAdmin?"ADMINISTRATION":"YOUR SPACE"}</div><nav className="side-nav">{nav.map(([href,label,Icon])=><Link key={href} href={href} onClick={()=>setMobile(false)} className={`side-link ${path===href?"active":""}`}><Icon size={18}/><span>{label}</span>{href==="/notifications"&&unread>0&&<i className="unread-dot">{unread}</i>}</Link>)}</nav><div className="sidebar-bottom"><div className="mini-profile"><div className="avatar">{initials(me?.full_name)}</div><div className="mini-person"><b title={isAdmin?me?.email:me?.full_name}>{isAdmin?(me?.email||"Loading account…"):(me?.full_name||"Loading…")}</b><span>{isAdmin?"Administrator":nice(me?.account_status||"student")}</span></div><ChevronDown size={15}/></div><button className="side-link logout-link" onClick={logout}><LogOut size={18}/><span>Sign out</span></button></div></aside>
  {mobile&&<button className="mobile-scrim" aria-label="Close menu" onClick={()=>setMobile(false)}/>}
  <main className="portal-main"><header className="portal-header"><button className="icon-button mobile-menu" onClick={()=>setMobile(!mobile)} aria-label="Toggle menu"><Menu size={19}/></button><div><span className="eyebrow">SKILLSWAP</span><h1>{title}</h1></div><div className="header-right"><ThemeControl/><Link className="header-notify" href="/notifications" aria-label="Notifications"><Bell size={19}/>{unread>0&&<i>{unread}</i>}</Link><div className={`header-person ${isAdmin?"admin":"student"}`} title={isAdmin?me?.email:me?.email}><div className="avatar small">{initials(me?.full_name)}</div><span className="header-identity"><b>{isAdmin?(me?.email||"Loading account…"):(me?.full_name?.split(" ")[0]||"Loading…")}</b>{!isAdmin&&<small>{me?.email}</small>}</span></div></div></header>
   <section className="portal-content">{error&&<div className="notice error" role="alert">{error}</div>}{notice&&<div className="notice success" role="status"><CheckCircle2 size={17}/>{notice}</div>}{loading?<div className="loading-card"><span className="spinner dark"/> Loading your SkillSwap…</div>:renderContent()}</section>
   <SkillModal modal={modal} data={data} onClose={()=>setModal(null)} onSubmit={async body=>{if(modal?.type==="request")await act("/api/swaps","POST",{requestedSkillId:modal.skill.id,offeredSkillId:body.offeredSkillId,message:body.message},"Swap request sent.");else if(modal?.type==="editSkill")await act(`/api/skills/${modal.skill.id}`,"PATCH",body,"Skill updated.");else await act("/api/skills","POST",body,"Skill saved.");}}/>
  </main>
 </div>;

 function renderContent(){
  if(!me)return <Empty icon={ShieldCheck} title="Session unavailable" copy="Sign in again to continue."/>;
  if(path.startsWith("/admin")&&me.role!=="admin")return <Empty icon={ShieldCheck} title="Administrator access required" copy="This page is only available to administrators."/>;
  if(path==="/dashboard")return <Dashboard me={me} data={data} onNavigate={router.push}/>;
  if(path==="/credits")return <CreditsPage data={data} onMore={loadMoreCredits}/>;
  if(path==="/leaderboard")return <LeaderboardPage data={data} scope={leaderboardScope} setScope={setLeaderboardScope} filter={leaderboardFilter} setFilter={setLeaderboardFilter} department={leaderboardDepartment} setDepartment={setLeaderboardDepartment}/>;
  if(path==="/pending")return <Pending me={me} data={data}/>;
  if(path==="/explore")return <Explore me={me} data={data} filter={filter} setFilter={setFilter} onRequest={(skill)=>setModal({type:"request",skill})}/>;
  if(path==="/my-skills")return <MySkills data={data} onAdd={(type)=>setModal({type:"skill",skillType:type})} onDelete={(id)=>act(`/api/skills/${id}`,"DELETE",null,"Skill removed.")} onToggle={(skill)=>act(`/api/skills/${skill.id}`,"PATCH",{isActive:!skill.is_active},"Skill status updated.")}/>;
  if(path==="/swap-requests"||path==="/my-exchanges")return <Swaps data={data} me={me} page={path} tab={tab} setTab={setTab} onAction={(id,action)=>act(`/api/swaps/${id}`,"PATCH",{action},`Exchange ${action}ed.`)}/>;
  if(path==="/notifications")return <Notifications data={data} onRead={(id)=>act("/api/notifications","PATCH",id?{id}:{readAll:true},"Notifications marked as read.")}/>;
  if(path==="/profile")return <Profile me={me} data={data} onSave={(body)=>act("/api/profile","PATCH",body,"Profile updated.")}/>;
  if(studentId)return <PublicStudentProfile data={data} me={me}/>;
  if(path==="/settings")return <SettingsView/>;
  if(path==="/admin")return <AdminHome data={data} me={me}/>;
  if(path==="/admin/credits")return <AdminCreditsPage data={data} scope={adminCreditScope} setScope={setAdminCreditScope} onRefresh={load}/>;
  if(path==="/admin/users")return <AdminUsers data={data} onAction={(id,status)=>act(`/api/admin/users/${id}`,"PATCH",{status},`Account ${status}.`)} onReset={async id=>{try{const r=await request(`/api/admin/users/${id}/reset-password`,"POST",{});setNotice(r.message);if(r.resetUrl){await navigator.clipboard?.writeText(r.resetUrl);window.alert(`${r.message}\n\n${r.resetUrl}`);}}catch(e){setError(e.message);}}}/>;
  if(path==="/admin/skills")return <AdminSkills data={data} onAction={(id,isActive)=>act("/api/admin/skills","PATCH",{id,isActive},"Skill listing updated.")}/>;
  if(path==="/admin/categories")return <Categories data={data} error={error} busy={busy} onRetry={load} onAdd={(body)=>act("/api/admin/categories","POST",body,"Category added.")} onUpdate={(id,body)=>act(`/api/admin/categories/${id}`,"PATCH",body,"Category updated.")} onDelete={(id)=>act(`/api/admin/categories/${id}`,"DELETE",undefined,"Category deleted.")}/>;
  if(path==="/admin/swaps")return <AdminSwaps data={data}/>;
  return <Empty title="Page not found" copy="Choose a page from the menu."/>;
 }
}

function Dashboard({me,data,onNavigate}){const h=new Date().getHours(),greeting=h<12?"Good morning":h<18?"Good afternoon":"Good evening",stats=data.stats||{},credit=data.credits?.summary;return <>
 {credit&&<Link href="/credits" className="credit-overview"><span><Sparkles size={19}/> SkillSwap Credits</span><b>{credit.credits} <small>{credit.level?.name}</small></b><i>{credit.learningContributions} learning · {credit.teachingContributions} teaching contributions</i></Link>}
 <div className="welcome-card"><div><span className="eyebrow">YOUR LEARNING JOURNEY</span><h2>{greeting}, {me?.full_name?.split(" ")[0]} <span>✦</span></h2><p>Ready to learn something new today?</p></div><div className="welcome-quote">“The best way to learn is to share what you know.”</div></div>
 <div className="stat-grid">{[[BookOpen,stats.skills_offered,"Skills offered"],[Sparkles,stats.skills_wanted,"Skills wanted"],[Clock3,stats.pending_requests,"Pending requests"],[CheckCircle2,stats.completed_exchanges,"Completed exchanges"]].map(([Icon,n,label])=><div className="stat-card" key={label}><span className="stat-icon"><Icon size={18}/></span><strong>{n??0}</strong><span>{label}</span></div>)}</div>
 <div className="section-heading"><div><span className="eyebrow">KEEP THE MOMENTUM</span><h2>Quick actions</h2></div></div><div className="quick-grid">{[[Plus,"Add a skill","Share something you know","/my-skills"],[Compass,"Find new skills","Discover what others teach","/explore"],[ArrowDownLeft,"Swap requests","See who wants to connect","/swap-requests"],[UserRound,"Edit profile","Tell others a little about you","/profile"]].map(([Icon,t,c,url])=><Link href={url} className="quick-card" key={t}><span><Icon size={18}/></span><b>{t}</b><small>{c}</small><ArrowRight className="quick-arrow" size={16}/></Link>)}</div>
 <div className="content-columns"><section><div className="section-heading compact"><div><span className="eyebrow">A GOOD PLACE TO START</span><h2>Skills to explore</h2></div><Link className="text-link" href="/explore">See all <ArrowRight size={14}/></Link></div><div className="mini-skill-grid">{(data.recommended||[]).length?data.recommended.map(s=><SkillCard key={s.id} skill={s} compact/>):<Empty title="New skills are on the way" copy="Check back soon or explore all available skills."/>}</div></section><section className="activity-panel"><div className="section-heading compact"><div><span className="eyebrow">STAY IN THE LOOP</span><h2>Recent activity</h2></div></div>{data.recent?.length?data.recent.map(n=><Link href={n.related_swap_id?"/swap-requests":"/notifications"} className="activity-row" key={n.id}><span className="activity-icon"><Bell size={16}/></span><span><b>{n.title}</b><small>{n.body}</small></span><time>{new Date(n.created_at).toLocaleDateString()}</time></Link>):<Empty title="A quiet moment" copy="Your latest requests and updates will appear here."/>}</section></div>
 </>;}

function CountUp({value}){const [shown,setShown]=useState(0);useEffect(()=>{const target=Math.max(0,Number(value)||0),reduce=window.matchMedia("(prefers-reduced-motion: reduce)").matches;let frame,start;if(reduce){frame=requestAnimationFrame(()=>setShown(target));return()=>cancelAnimationFrame(frame);}const tick=now=>{if(start===undefined)start=now;const progress=Math.min(1,(now-start)/850);setShown(Math.floor(target*(1-Math.pow(1-progress,3))));if(progress<1)frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);return()=>cancelAnimationFrame(frame);},[value]);return <>{new Intl.NumberFormat().format(shown)}</>;}
const achievementIcons={"first-steps":FootstepsIcon,"skill-sharer":HandHeart,"curious-mind":Brain,"knowledge-builder":BookOpen,"dedicated-learner":Lightbulb,"helpful-mentor":GraduationCap,"community-star":Star,"community-champion":Crown};
function FootstepsIcon({size=20}){return <ArrowUpRight size={size}/>;}
const earnGuide=[["Learning contribution","Complete a learning side of an exchange",50,BookOpen],["Teaching contribution","Complete the teaching side of an exchange",40,GraduationCap],["Mutual completion","Both students confirm an exchange",10,CheckCheck],["Complete profile","One time after filling your profile",15,UserRound],["First approved teaching skill","One time after publishing an approved skill",10,Sparkles],["First exchange milestone","One time after your first completed exchange",20,Medal]];
const creditLevelOrder=["Newcomer","Explorer","Contributor","Mentor","Community Champion"];
function CreditsPage({data,onMore}){const summary=data.summary||{},credits=Number(summary.credits)||0,level=summary.level||{name:"Newcomer",description:"Every shared skill starts with a first step.",currentLevelAt:0,nextLevelAt:100,progress:0},achievements=summary.achievements||[],unlocked=achievements.filter(item=>item.earned).length,remaining=level.nextLevelAt===null?0:Math.max(0,level.nextLevelAt-credits),isMax=level.nextLevelAt===null,pagination=data.pagination||{total:(data.activity||[]).length,hasMore:false};const [loadingMore,setLoadingMore]=useState(false),[levelUp,setLevelUp]=useState(false);useEffect(()=>{const current=creditLevelOrder.indexOf(level.name),key="skillswap-last-credit-level",previous=localStorage.getItem(key);if(previous!==null&&current>Number(previous))requestAnimationFrame(()=>setLevelUp(true));localStorage.setItem(key,String(current));},[level.name]);async function more(){setLoadingMore(true);try{await onMore?.();}finally{setLoadingMore(false);}}const stats=[[BookOpen,"Learning contributions",summary.learningContributions||0,"Skills you have learned", "learning"],[GraduationCap,"Teaching contributions",summary.teachingContributions||0,"Skills you have shared","teaching"],[ArrowLeftRight,"Completed exchanges",summary.completedExchanges||0,"Two way learning moments","exchange"],[Award,"Achievements unlocked",unlocked,`${achievements.length} badges to collect`,"achievement"]];return <div className="credits-page">
 {levelUp&&<motion.div className="credits-level-up" role="status" initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}}><span><Trophy size={17}/></span><b>Level unlocked: {level.name}</b><small>Your recent SkillSwap activity moved you up a level.</small><button aria-label="Dismiss level-up message" onClick={()=>setLevelUp(false)}><X size={15}/></button></motion.div>}
 <motion.section className="credits-hero" initial={{opacity:0,y:14}} animate={{opacity:1,y:0}} transition={{duration:.42}}><div className="credits-hero-copy"><span className="eyebrow">SKILLSWAP CREDITS</span><h2>My Learning Journey</h2><p>Every exchange adds to the knowledge you share and the skills you grow.</p><div className="credits-hero-level"><span className="credits-level-mark"><Trophy size={19}/></span><span><b>{level.name}</b><small>{level.description||"Your progress grows with every exchange."}</small></span></div><div className="credits-hero-links"><Link href="/explore" className="primary-button">Explore skills <ArrowRight size={15}/></Link><Link href="#credit-activity" className="credits-inline-link">View all history <ArrowDownLeft size={15}/></Link></div></div><div className="credits-total-card"><span className="credits-total-label"><Sparkles size={16}/> YOUR TOTAL</span><strong><CountUp value={credits}/></strong><span className="credits-total-caption">SkillSwap Credits</span><span className="credits-coin"><Sparkles size={19}/></span><small>{CREDIT_DISCLAIMER}</small></div></motion.section>
 <motion.section className="credits-level-card" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:.08,duration:.4}}><div className="credits-level-top"><div><span className="eyebrow">LEVEL PROGRESS</span><h3>{level.name}</h3></div><span className="credits-level-icon">{isMax?<Crown size={22}/>:<Medal size={22}/>}</span></div><p>{isMax?"You’ve reached the highest level. Keep sharing what you know.":remaining===0?"Your next level is ready to unlock.":`${remaining} credits until ${level.nextLevelAt===500?"Mentor":level.nextLevelAt===250?"Contributor":level.nextLevelAt===100?"Explorer":"Community Champion"}.`}</p><div className="credits-progress-meta"><b>{credits.toLocaleString()} credits</b><span>{isMax?"Maximum level":`${Number(level.nextLevelAt).toLocaleString()} to next level`}</span></div><div className="credits-progress-track" role="progressbar" aria-label="Progress to next level" aria-valuemin="0" aria-valuemax="100" aria-valuenow={isMax?100:level.progress}><motion.i initial={{width:0}} animate={{width:`${isMax?100:level.progress}%`}} transition={{duration:.85,ease:"easeOut"}}/></div><div className="credits-level-foot"><span>{isMax?"Community Champion":"Keep learning, teaching, and confirming exchanges."}</span>{!isMax&&<b>{remaining} to go</b>}</div></motion.section>
 <section className="credits-stats-grid" aria-label="Contribution statistics">{stats.map(([Icon,label,value,detail,kind],index)=><motion.article className={`credits-stat-card ${kind}`} key={label} initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} transition={{delay:.04*index,duration:.35}}><span className="credits-stat-icon"><Icon size={18}/></span><small>{label}</small><strong><CountUp value={value}/></strong><span>{detail}</span></motion.article>)}</section>
 {(summary.learningContributions||summary.teachingContributions||summary.completedExchanges)?null:<div className="credits-empty-note"><Sparkles size={18}/><span>Your first completed exchange will add learning, teaching, and completion stats. Start with an available skill.</span><Link href="/my-exchanges">View exchanges <ArrowRight size={14}/></Link></div>}
 <section className="credits-section" id="achievements"><div className="credits-section-heading"><div><span className="eyebrow">MILESTONES</span><h3>Achievements</h3><p>Earned through your real SkillSwap activity.</p></div><span className="credits-earned-count"><Award size={15}/>{unlocked} of {achievements.length} unlocked</span></div><div className="credits-achievement-grid">{achievements.map((badge,index)=>{const Icon=achievementIcons[badge.id]||Award;return <motion.article className={`credits-badge-card ${badge.earned?"earned":"locked"}`} key={badge.id} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:index*.035,duration:.3}}><span className="credits-badge-icon"><Icon size={21}/></span><span className={`credits-badge-state ${badge.earned?"unlocked":"locked"}`}>{badge.earned?<><CheckCircle2 size={12}/> Unlocked</>:"In progress"}</span><h4>{badge.name}</h4><p>{badge.requirement}</p>{badge.earned?<small className="credits-badge-date">Earned through your activity</small>:<><div className="credits-badge-progress"><i style={{width:`${badge.progress}%`}}/></div><small>{badge.current} / {badge.target} progress</small></>}</motion.article>;})}</div></section>
 <section className="credits-section credits-activity-section" id="credit-activity"><div className="credits-section-heading"><div><span className="eyebrow">YOUR LEDGER</span><h3>Credit Activity</h3><p>Recent credits earned and adjustments recorded to your account.</p></div><span className="credits-activity-total">{pagination.total||0} transactions</span></div>{(data.activity||[]).length?<div className="credits-activity-list">{data.activity.map((item,index)=>{const adjustment=item.transaction_type==="adjustment",Icon=adjustment?Settings:item.activity_type==="learning"?BookOpen:item.activity_type==="teaching"?GraduationCap:item.activity_type==="mutual_completion"?CheckCheck:item.activity_type==="admin_adjustment"?Settings:Sparkles;const category=adjustment?"Admin adjustment":(item.activity_type||"Activity").replaceAll("_"," ").replace(/\b\w/g,c=>c.toUpperCase());return <motion.article className="credits-activity-row" key={item.id} initial={{opacity:0,x:-8}} animate={{opacity:1,x:0}} transition={{delay:Math.min(index*.025,.2),duration:.28}}><span className={`credits-activity-icon ${Number(item.amount)>=0?"positive":"negative"}`}><Icon size={17}/></span><span className="credits-activity-copy"><b>{item.description}</b><small>{category}{adjustment&&item.reason?` · Reason: ${item.reason}`:""}</small></span><time dateTime={item.created_at}>{new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric",year:"numeric"}).format(new Date(item.created_at))}</time><strong className={Number(item.amount)>=0?"positive":"negative"}>{Number(item.amount)>0?"+":""}{Number(item.amount).toLocaleString()} <small>credits</small></strong></motion.article>;})}</div>:<div className="credits-history-empty"><span className="credits-stat-icon"><Activity size={20}/></span><h4>No credit activity yet</h4><p>Completed exchanges and eligible milestones will appear here when recorded.</p></div>}{pagination.hasMore&&<div className="credits-load-more"><button className="secondary-button" onClick={more} disabled={loadingMore}>{loadingMore?"Loading activity…":"Load more activity"}<ArrowDownLeft size={15}/></button></div>}</section>
 <section className="credits-section credits-earn-section"><div className="credits-section-heading"><div><span className="eyebrow">WAYS TO GROW</span><h3>How to earn credits</h3><p>Credits are community recognition points, not money.</p></div><Sparkles className="credits-earn-spark" size={22}/></div><div className="credits-earn-grid">{earnGuide.map(([title,detail,amount,Icon])=><article className="credits-earn-row" key={title}><span><Icon size={17}/></span><div><b>{title}</b><small>{detail}</small></div><strong>+{amount}</strong></article>)}</div><div className="credits-footer-links"><Link href="/explore">Explore skills <ArrowRight size={14}/></Link><Link href="/my-skills">My skills <ArrowRight size={14}/></Link><Link href="/my-exchanges">My exchanges <ArrowRight size={14}/></Link></div><p className="credits-disclaimer">{CREDIT_DISCLAIMER}</p></section>
 </div>;}
function LeaderboardPage({data,scope,setScope,filter,setFilter,department,setDepartment}){
 const students=data.students||[],top=students.slice(0,3),rest=students.slice(3),summary=data.summary||{},categoryLabel={overall:"Overall",all_time:"All time",learning:"Learning contributions",teaching:"Teaching contributions",monthly:"This month"}[filter]||"Overall";
 return <div className="leaderboard-page"><div className="leaderboard-heading"><span className="eyebrow">SKILLSWAP COMMUNITY</span><h2>Student Leaderboard</h2><p>Celebrate the students who learn, teach, and grow together.</p></div>
  <div className="leaderboard-filters"><label>Community<select value={scope} onChange={e=>setScope(e.target.value)}><option value="real">Student community</option><option value="demo">Demo Community</option></select></label><label>Ranking category<select value={filter} onChange={e=>setFilter(e.target.value)}>{[["overall","Overall"],["all_time","All time"],["learning","Learning contributions"],["teaching","Teaching contributions"],["monthly","Monthly"]].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label>Department<select value={department} onChange={e=>setDepartment(e.target.value)}><option value="">All departments</option>{(data.departments||[]).map(d=><option key={d}>{d}</option>)}</select></label></div>
  <div className="leaderboard-summary"><article><small>Your rank</small><b>{data.userRank?`#${data.userRank.rank}`:"—"}</b><span>{data.userRank?`${data.userRank.score} credits · ${categoryLabel}`:"Not listed in this community"}</span></article><article><small>Participating students</small><b>{summary.total_students||0}</b><span>{data.demoLabel||"Visible approved students"}</span></article><article><small>Highest score</small><b>{summary.highest_score||0}</b><span>{categoryLabel}</span></article><article><small>Current category</small><b>{categoryLabel}</b><span>{department||"All departments"}</span></article></div>
  {top.length>0&&<section className="leaderboard-podium" aria-label="Top three students">{top.map(s=><Link href={`/students/${s.id}`} key={s.id} className={`podium-card rank-${s.rank}`}><span className="podium-medal">{Number(s.rank)===1?"🥇":Number(s.rank)===2?"🥈":"🥉"}</span><span className="avatar podium-avatar">{initials(s.full_name)}</span><b>{s.full_name}{s.is_demo&&<i className="demo-tag">Demo</i>}</b><small>{s.department}</small><span className="level-pill">{s.level.name}</span><strong>{s.score} <small>credits</small></strong></Link>)}</section>}
  <section className="leaderboard-results"><div className="section-heading compact"><div><span className="eyebrow">RANKINGS</span><h2>{data.demoLabel||"Student community"}</h2></div><span className="result-count">{summary.total_students||0} students</span></div>{rest.length>0?<div className="leaderboard-table-wrap"><table className="leaderboard-table"><thead><tr><th>Rank</th><th>Student</th><th>Department</th><th>Level</th><th>Learning</th><th>Teaching</th><th>Credits</th></tr></thead><tbody>{rest.map(s=><tr key={s.id}><td className="rank-cell">#{s.rank}</td><td><Link className="leader-student" href={`/students/${s.id}`}><span className="avatar small">{initials(s.full_name)}</span><b>{s.full_name}{s.is_demo&&<i className="demo-tag">Demo</i>}</b></Link></td><td>{s.department}</td><td><span className="level-pill">{s.level.name}</span></td><td>{s.learning_contributions}</td><td>{s.teaching_contributions}</td><td><b>{s.credits}</b></td></tr>)}</tbody></table></div>:top.length===0&&<Empty icon={Users} title="No students are listed yet" copy="Approved students appear here as they earn SkillSwap Credits."/>}</section>
 </div>;
}function StarRating({rating,count}){return <span className="review-rating" aria-label={`${rating} out of 5 stars`}><span aria-hidden="true">{[1,2,3,4,5].map(n=><Star key={n} size={14} fill={n<=Math.round(Number(rating))?"currentColor":"none"}/>)}</span><b>{Number(rating).toFixed(1)}</b>{count!=null&&<small>({count} reviews)</small>}</span>}
function AchievementList({achievements=[]}){return <div className="achievement-grid">{achievements.map(a=><article className={`achievement-card ${a.earned?"earned":"locked"}`} key={a.id}><span className="achievement-icon"><Sparkles size={17}/></span><b>{a.name}</b><small>{a.requirement}</small><div className="achievement-progress"><i style={{width:`${a.progress||0}%`}}/></div><span className="achievement-progress-label">{a.earned?"Earned":`${a.current||0} / ${a.target||1}`}</span></article>)}</div>}
function StudentSkillList({skills=[],type}){const items=skills.filter(s=>s.skill_type===type);return items.length?<div className="portfolio-skill-list">{items.map(s=><article className="portfolio-skill" key={s.id}><div><b>{s.name}</b><span className="skill-level">{nice(s.level||"beginner")}</span></div><small>{s.category||"Skill"}</small><p>{s.description|| (type==="wanted"?"Looking for guided practice and useful feedback.":"Available to share practical knowledge and examples.")}</p></article>)}</div>:<Empty icon={BookOpen} title={type==="wanted"?"No learning goals yet":"No teaching skills listed yet"} copy={type==="wanted"?"Learning goals will appear here when this student adds them.":"This student has not listed a teaching skill yet."}/>}
function HistoryList({history=[]}){return history.length?<div className="profile-history">{history.map(x=><article className="profile-history-row" key={x.id}><span className="avatar small">{initials(x.other_student)}</span><div><b>{x.other_student}</b><small>{x.offered_skill} ↔ {x.requested_skill}</small><small>Completed {new Date(x.completed_at).toLocaleDateString()} · {x.review_count>=2?"Both reviewed":x.review_count?"One review":"No reviews yet"}</small></div><strong>+{x.credits_earned}<small>credits</small></strong></article>)}</div>:<Empty icon={Activity} title="No completed exchanges yet" copy="Completed skill exchanges will show here."/>}
function PublicStudentProfile({data,me}){const p=data.profile||{},s=data.summary||{},own=me?.id===p.id;return <div className="student-portfolio"><header className="portfolio-header"><div className="avatar profile-avatar">{initials(p.full_name)}</div><div className="portfolio-identity"><span className="eyebrow">STUDENT PORTFOLIO {p.is_demo&&<i className="demo-tag">Demo</i>}</span><h2>{p.full_name}</h2><p>{p.department} · {p.academic_year}</p><p>{p.bio||"This student is building skills through teaching and shared learning."}</p><div className="portfolio-level"><span className="level-pill">{s.level?.name||"Newcomer"}</span><b>{s.credits||0} SkillSwap Credits</b></div></div>{own&&<Link href="/profile" className="secondary-button">Edit profile <ArrowRight size={15}/></Link>}</header>
 <div className="portfolio-stats">{[["Completed exchanges",p.completed_exchanges||0],["Average rating",p.review_count?Number(p.average_rating).toFixed(1):"New member"],["Total reviews",p.review_count||0],["Skills offered",data.skills?.filter(x=>x.skill_type==="offered").length||0],["Skills wanted",data.skills?.filter(x=>x.skill_type==="wanted").length||0],["SkillSwap Credits",s.credits||0]].map(([label,value])=><article key={label}><small>{label}</small><b>{value}</b>{label==="Average rating"&&p.review_count>0&&<StarRating rating={p.average_rating}/>}</article>)}</div>
 <div className="portfolio-two-column"><section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">SHARED KNOWLEDGE</span><h2>Skills I Can Teach</h2></div></div><StudentSkillList skills={data.skills} type="offered"/></section><section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">LEARNING NEXT</span><h2>Skills I Want to Learn</h2></div></div><StudentSkillList skills={data.skills} type="wanted"/></section></div>
 <section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">LEARNING HISTORY</span><h2>Recent completed exchanges</h2></div></div><HistoryList history={data.history}/></section>
 <section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">MILESTONES</span><h2>Achievements</h2></div></div><AchievementList achievements={s.achievements||[]}/></section>
 <section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">COMMUNITY FEEDBACK</span><h2>Reviews</h2></div>{p.review_count>0?<StarRating rating={p.average_rating} count={p.review_count}/>:<span className="new-member-label">New member · No reviews yet</span>}</div>{data.reviews?.length?<div className="review-list">{data.reviews.map(r=><article className="review-card" key={r.id}><div><b>{r.reviewer_name}</b><StarRating rating={r.rating}/></div><span className="review-skill-pair">{r.offered_skill} ↔ {r.requested_skill}</span><p>{r.comment||"Shared a helpful learning session."}</p><small>{new Date(r.created_at).toLocaleDateString()}</small></article>)}</div>:<Empty icon={Star} title="No reviews yet" copy="Reviews appear after this student completes an exchange."/>}</section>
 </div>}function AdminCreditsPage({data,scope,setScope,onRefresh}){const[id,setId]=useState(''),[detail,setDetail]=useState(null),[error,setError]=useState('');async function select(v){setId(v);try{setDetail((await request(`/api/admin/credits?scope=${scope}&userId=${v}`)).detail)}catch(e){setError(e.message)}}async function submit(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await request('/api/admin/credits','POST',{userId:id,amount:Number(f.get('amount')),reason:f.get('reason')});await select(id);await onRefresh()}catch(e){setError(e.message)}}return <><select value={scope} onChange={e=>setScope(e.target.value)}>{['all','demo','real'].map(x=><option key={x}>{x}</option>)}</select><div>{(data.students||[]).map(s=><button key={s.id} onClick={()=>select(s.id)}>{s.full_name}{s.is_demo?' · Demo':''} · {s.credits}</button>)}</div>{error&&<p>{error}</p>}{detail&&<><h2>{detail.student.full_name} · {detail.summary.credits} credits</h2><form onSubmit={submit}><label>Amount<input name="amount" type="number" min="-5000" max="5000" required/></label><label>Reason<textarea name="reason" minLength="8" maxLength="500" required/></label><button className="primary-button">Record adjustment</button></form>{detail.duplicateEvents?.length>0&&<p role="alert">Duplicate earning events need review: {detail.duplicateEvents.length}</p>}{detail.transactions.map(t=><p key={t.id}>{t.amount} · {t.reason||t.description}</p>)}</>}</>}
function Pending({me,data}){const status=me?.account_status;return <div className="pending-wrap"><div className={`approval-card ${status}`}><span className="approval-icon">{status==="pending"?<Clock3/>:status==="approved"?<Check/>:<ShieldCheck/>}</span><span className="eyebrow">ACCOUNT STATUS</span><h2>{status==="pending"?"Your application is in review":status==="rejected"?"Your application was not approved":"Welcome to SkillSwap"}</h2><p>{status==="pending"?"Your account is awaiting administrator approval. You can explore SkillSwap while we review your profile.":status==="rejected"?"Your account is not active. If you believe this is a mistake, contact your administrator for help.":"Your account is approved. You can now list skills and request exchanges."}</p>{status==="rejected"&&me?.status_note&&<p className="admin-note">Administrator note: {me.status_note}</p>}<Status value={status}/><div className="approval-actions">{status!=="rejected"&&<Link className="secondary-button" href="/profile">Complete my profile</Link>}{status!=="rejected"&&<Link className="primary-button" href="/explore">Browse skills <ArrowRight size={17}/></Link>}{status==="rejected"&&data.contactEmail&&<a className="primary-button" href={`mailto:${data.contactEmail}?subject=SkillSwap%20account%20review`}>Contact administrator <ArrowRight size={17}/></a>}</div></div><div className="pending-side"><div className="info-card"><GraduationCap size={21}/><h3>What happens next?</h3><p>An administrator will review your student profile. You can browse available skills while you wait.</p></div><div className="info-card"><BookOpen size={21}/><h3>Explore read-only</h3><p>Take a look around and discover what other approved students are excited to teach.</p></div></div></div>;}

function SkillCard({skill,compact=false,onRequest}){return <article className={`skill-card ${compact?"compact":""}`}><div className="skill-card-top"><span className="skill-category">{skill.category||"Skill"}</span><span className="skill-level">{nice(skill.level||"beginner")}</span></div><h3>{skill.name}</h3><p className="skill-description">{skill.description||"Ready to share this skill with another student."}</p><div className="skill-owner"><span className="avatar small">{initials(skill.full_name)}</span><span><b><Link href={`/students/${skill.user_id}`}>{skill.full_name}</Link>{skill.is_demo&&<i className="demo-tag">Demo</i>}</b><small>{skill.department||"Student"}</small></span>{Number(skill.review_count)>0?<span className="rating"><Star size={14} fill="currentColor"/>{Number(skill.rating).toFixed(1)} <small>({skill.review_count})</small></span>:<span className="new-member-label">No reviews yet</span>}</div><div className="skill-owner-stats"><span>{skill.completed_exchanges||0} exchanges</span><span className="level-pill">{skill.student_level?.name||"Newcomer"}</span></div>{onRequest&&<button className="secondary-button full" onClick={()=>onRequest(skill)}>Request swap <ArrowRight size={16}/></button>}</article>;}

function Explore({me,data,filter,setFilter,onRequest}){const f=(k,v)=>setFilter(old=>({...old,[k]:v}));return <><div className="page-intro"><div><span className="eyebrow">FIND YOUR NEXT LEARNING PARTNER</span><h2>Skills shared by students</h2><p>Search, explore, and find someone to learn from.</p></div><span className="result-count">{data.skills?.length||0} skills</span></div>{me?.account_status!=="approved"&&<div className="notice warning">Your account is awaiting administrator approval. Browsing is available while you wait; exchange requests unlock after approval.</div>}<div className="filter-panel"><label className="search-box"><Search size={18}/><input value={filter.q} onChange={e=>f("q",e.target.value)} placeholder="Search skills, people, or categories"/></label><label><span>Category</span><select value={filter.category} onChange={e=>f("category",e.target.value)}><option value="">All categories</option>{data.categories?.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label><span>Level</span><select value={filter.level} onChange={e=>f("level",e.target.value)}><option value="">Any level</option>{["beginner","intermediate","advanced","expert"].map(x=><option key={x} value={x}>{nice(x)}</option>)}</select></label><label><span>Rating</span><select value={filter.rating||""} onChange={e=>f("rating",e.target.value)}><option value="">Any rating</option><option value="3">3+ stars</option><option value="4">4+ stars</option><option value="5">5 stars</option></select></label><label><span>Department</span><select value={filter.department} onChange={e=>f("department",e.target.value)}><option value="">All departments</option>{data.departments?.map(x=><option key={x}>{x}</option>)}</select></label><label><span>Academic year</span><select value={filter.year} onChange={e=>f("year",e.target.value)}><option value="">Any year</option>{["Year 1","Year 2","Year 3","Year 4","Graduate","Other"].map(x=><option key={x}>{x}</option>)}</select></label><button className="clear-filter" onClick={()=>setFilter({q:"",category:"",level:"",department:"",year:"",rating:""})}><SlidersHorizontal size={15}/> Clear filters</button></div><div className="skill-grid">{data.skills?.length?data.skills.map(s=><SkillCard key={s.id} skill={s} onRequest={me?.account_status==="approved"?onRequest:undefined}/>):<Empty icon={Search} title="No skills match those filters" copy="Try broadening your search or clearing one of the filters."/>}</div></>;}

function MySkills({data,onAdd,onEdit,onDelete,onToggle}){const offered=(data.skills||[]).filter(x=>x.skill_type==="offered"),wanted=(data.skills||[]).filter(x=>x.skill_type==="wanted");return <><div className="page-intro"><div><span className="eyebrow">YOUR SKILL PROFILE</span><h2>What can you teach?</h2><p>Add skills you can teach and skills you’d like to learn.</p></div></div><div className="skill-tabs"><section className="owned-skill-section"><div className="section-heading compact"><div><span className="eyebrow">SHARE WHAT YOU KNOW</span><h2>Skills I can teach <small>{offered.length}</small></h2></div><button className="primary-button small-button" onClick={()=>onAdd("offered")}><Plus size={16}/> Add skill</button></div>{offered.length?<div className="owned-list">{offered.map(s=><SkillRow key={s.id} skill={s} onEdit={onEdit} onDelete={onDelete} onToggle={onToggle}/>)}</div>:<Empty title="No teaching skills yet" copy="Share your strengths so others can learn from you."/>}</section><section className="owned-skill-section"><div className="section-heading compact"><div><span className="eyebrow">GROW SOMETHING NEW</span><h2>Skills I want to learn <small>{wanted.length}</small></h2></div><button className="secondary-button small-button" onClick={()=>onAdd("wanted")}><Plus size={16}/> Add skill</button></div>{wanted.length?<div className="owned-list">{wanted.map(s=><SkillRow key={s.id} skill={s} onEdit={onEdit} onDelete={onDelete} onToggle={onToggle}/>)}</div>:<Empty title="Add a learning goal" copy="Choose a skill you’d love to learn from another student."/>}</section></div></>;}
function SkillRow({skill,onEdit,onDelete,onToggle}){return <div className={`owned-row ${!skill.is_active?"inactive":""}`}><span className="owned-icon"><BookOpen size={17}/></span><span className="owned-detail"><b>{skill.name}</b><small>{skill.category||"Other"} · {nice(skill.level)} {skill.is_active?"":"· Hidden from discovery"}</small></span><button className="icon-button" title="Edit skill" onClick={()=>onEdit(skill)}><SlidersHorizontal size={16}/></button><button className="icon-button" title={skill.is_active?"Deactivate":"Activate"} onClick={()=>onToggle(skill)}><Eye size={17}/></button><button className="icon-button danger-icon" title="Remove skill" onClick={()=>window.confirm(`Remove ${skill.name}?`)&&onDelete(skill.id)}><Trash2 size={17}/></button></div>;}

function Swaps({data,me,page,tab,setTab,onAction}){const all=data.swaps||[],tabs=[["all","All"],["pending","Pending"],["accepted","Accepted"],["completed","Completed"],["closed","Rejected / Cancelled"]],visible=all.filter(s=>tab==="all"||s.status===tab||(tab==="closed"&&["rejected","cancelled"].includes(s.status)));return <><div className="page-intro"><div><span className="eyebrow">YOUR SKILL EXCHANGES</span><h2>{page==="/swap-requests"?"Requests & invitations":"Exchange history"}</h2><p>{page==="/swap-requests"?"Manage offers you’ve sent and received.":"Follow every exchange, from first hello to completed skill share."}</p></div><span className="result-count">{all.length} exchanges</span></div><div className="tab-strip">{tabs.map(([value,label])=><button key={value} className={tab===value?"active":""} onClick={()=>setTab(value)}>{label}{value!=="all"&&<small>{all.filter(s=>s.status===value||(value==="closed"&&["rejected","cancelled"].includes(s.status))).length}</small>}</button>)}</div>{visible.length?<div className="exchange-list">{visible.map(s=><ExchangeCard key={s.id} swap={s} me={me} page={page} onAction={onAction}/>)}</div>:<Empty icon={ArrowLeftRight} title={all.length?`No ${tab==="closed"?"rejected or cancelled":tab} exchanges`:"No exchanges here yet"} copy={all.length?"Try another status tab to see the rest of your exchange history.":"When you send or receive a request, it will appear here."} action={!all.length&&<Link href="/explore" className="secondary-button">Explore skills <ArrowRight size={15}/></Link>}/>}</>}
function ExchangeCard({swap:s,me,onAction}){const incoming=s.receiver_id===me?.id,partnerName=incoming?s.sender_name:s.receiver_name,selfConfirmed=incoming?s.receiver_completed_at:s.sender_completed_at,partnerConfirmed=incoming?s.sender_completed_at:s.receiver_completed_at;return <article className="exchange-card"><div className="exchange-head"><div className="exchange-person"><span className="avatar">{initials(partnerName)}</span><div><b>{partnerName}{s.is_demo&&<i className="demo-tag">Demo</i>}</b><small>{incoming?"Exchange partner · Request received":"Exchange partner · Request sent"} · {new Date(s.created_at).toLocaleDateString()}</small></div></div><Status value={s.status}/></div><div className="swap-summary"><div><small>REQUESTED</small><b>{s.requested_skill}</b></div><ArrowLeftRight size={17}/><div><small>OFFERED</small><b>{s.offered_skill}</b></div></div>{s.message&&<p className="swap-message">“{s.message}”</p>}
 {s.status==="accepted"&&<div className="exchange-next-step"><b>Next step</b><span>Arrange a time to share both skills. Each participant confirms when the exchange is complete.</span></div>}
 {s.status==="accepted"&&<div className="confirmation-progress"><span className={selfConfirmed?"confirmed":""}>{selfConfirmed?<CheckCircle2 size={15}/>:<Clock3 size={15}/>} You {selfConfirmed?"confirmed":"to confirm"}</span><span className={partnerConfirmed?"confirmed":""}>{partnerConfirmed?<CheckCircle2 size={15}/>:<Clock3 size={15}/>} Partner {partnerConfirmed?"confirmed":"to confirm"}</span>{selfConfirmed?<small>Thanks — waiting for your partner.</small>:<button className="secondary-button small-button" onClick={()=>onAction(s.id,"complete")}>Confirm exchange completed <CheckCircle2 size={15}/></button>}</div>}
 {s.status==="completed"&&<div className="exchange-completion"><span>Completed {new Date(s.completed_at).toLocaleDateString()}</span><span className="confirmation-progress compact-confirm"><CheckCircle2 size={15}/> Both participants confirmed</span><span className="credit-earned">+{s.credits_earned||0} credits earned</span></div>}
 {s.status==="pending"&&<div className="exchange-next-step"><b>{incoming?"Your response is needed":"Waiting for a response"}</b><span>{incoming?"Accept the request or decline it.":"The student you contacted has not responded yet."}</span></div>}
 <div className="exchange-actions">{s.status==="pending"&&incoming&&<><button className="secondary-button" onClick={()=>onAction(s.id,"reject")}>Decline</button><button className="primary-button" onClick={()=>onAction(s.id,"accept")}>Accept request <Check size={16}/></button></>}{s.status==="pending"&&!incoming&&<button className="text-link" onClick={()=>onAction(s.id,"cancel")}>Cancel request</button>}{s.status==="completed"&&(s.reviewed_by_me?<span className="review-status">You reviewed this exchange{ s.reviewed_by_partner?" · Partner reviewed":""}</span>:<details className="review-inline"><summary><Star size={15}/> Leave a review</summary><ReviewForm swap={s}/></details>)}</div></article>}function ReviewForm({swap}){const[score,setScore]=useState(5),[comment,setComment]=useState(""),[done,setDone]=useState(false),[err,setErr]=useState("");return done?<p className="success-text">Thanks for sharing your feedback.</p>:<form className="review-form" onSubmit={async e=>{e.preventDefault();setErr("");try{await request("/api/reviews","POST",{swapId:swap.id,rating:score,comment});setDone(true);}catch(x){setErr(x.message);}}}><label>Rating <select value={score} onChange={e=>setScore(Number(e.target.value))}>{[5,4,3,2,1].map(n=><option key={n} value={n}>{n} stars</option>)}</select></label><textarea value={comment} onChange={e=>setComment(e.target.value)} placeholder="A few words about the exchange" maxLength={600}/>{err&&<small className="error-text">{err}</small>}<button className="primary-button small-button">Send review</button></form>;}

function Notifications({data,onRead}){return <><div className="page-intro"><div><span className="eyebrow">YOUR ACTIVITY</span><h2>Notifications</h2><p>Updates about requests and exchanges.</p></div>{data.unreadCount>0&&<button className="secondary-button" onClick={()=>onRead(null)}><CheckCheck size={16}/> Mark all read</button>}</div>{data.notifications?.length?<div className="notification-list">{data.notifications.map(n=><article className={`notification-card ${n.read_at?"read":"unread"}`} key={n.id}><span className="notification-icon"><Bell size={17}/></span><div><b>{n.title}</b><p>{n.body}</p><small>{new Date(n.created_at).toLocaleString()}</small></div>{!n.read_at&&<button className="text-link" onClick={()=>onRead(n.id)}>Mark read</button>}{n.related_swap_id&&<Link href="/swap-requests" className="icon-button" aria-label="View request"><ArrowRight size={17}/></Link>}</article>)}</div>:<Empty icon={Bell} title="You’re all caught up" copy="New exchange updates will show up here."/>}</>;}

function Profile({me,data,onSave}){const p=data.profile||{},summary=data.credits?.summary||{},reviews=data.reviews||[];return <div className="student-portfolio"><header className="portfolio-header"><div className="avatar profile-avatar">{initials(me?.full_name)}</div><div className="portfolio-identity"><span className="eyebrow">MY STUDENT PORTFOLIO {me?.is_demo&&<i className="demo-tag">Demo</i>}</span><h2>{me?.full_name}</h2><p>{me?.department} · {me?.academic_year}</p><p>{me?.bio||"Add a short bio to tell the community what you enjoy teaching and learning."}</p><div className="portfolio-level"><span className="level-pill">{summary.level?.name||"Newcomer"}</span><b>{summary.credits||0} SkillSwap Credits</b></div></div><Link className="secondary-button" href="#profile-details">Edit profile <ArrowRight size={15}/></Link></header>
 <div className="portfolio-stats">{[["Completed exchanges",p.completed_exchanges||0],["Average rating",p.review_count?Number(p.average_rating).toFixed(1):"New member"],["Total reviews",p.review_count||0],["Skills offered",p.skills_offered||0],["Skills wanted",p.skills_wanted||0],["SkillSwap Credits",summary.credits||0]].map(([label,value])=><article key={label}><small>{label}</small><b>{value}</b>{label==="Average rating"&&p.review_count>0&&<StarRating rating={p.average_rating}/>}</article>)}</div>
 <div className="portfolio-two-column"><section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">SHARED KNOWLEDGE</span><h2>Skills I Can Teach</h2></div><Link href="/my-skills" className="text-link">Manage skills</Link></div><StudentSkillList skills={data.skills} type="offered"/></section><section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">LEARNING NEXT</span><h2>Skills I Want to Learn</h2></div><Link href="/my-skills" className="text-link">Manage goals</Link></div><StudentSkillList skills={data.skills} type="wanted"/></section></div>
 <section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">LEARNING HISTORY</span><h2>Recent completed exchanges</h2></div></div><HistoryList history={data.history}/></section>
 <section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">MILESTONES</span><h2>Achievements</h2></div></div><AchievementList achievements={summary.achievements||[]}/></section>
 <section className="portfolio-section"><div className="section-heading compact"><div><span className="eyebrow">COMMUNITY FEEDBACK</span><h2>Reviews</h2></div>{p.review_count>0?<StarRating rating={p.average_rating} count={p.review_count}/>:<span className="new-member-label">New member · No reviews yet</span>}</div>{reviews.length?<div className="review-list">{reviews.map(r=><article className="review-card" key={r.id}><div><b>{r.reviewer_name}</b><StarRating rating={r.rating}/></div><span className="review-skill-pair">{r.offered_skill} ↔ {r.requested_skill}</span><p>{r.comment||"Shared a helpful learning session."}</p><small>{new Date(r.created_at).toLocaleDateString()}</small></article>)}</div>:<Empty icon={Star} title="No reviews yet" copy="Reviews appear after you complete an exchange."/>}</section>
 <section className="portfolio-section form-card" id="profile-details"><div className="section-heading compact"><div><span className="eyebrow">MAKE IT YOURS</span><h2>Profile details</h2></div></div><ProfileForm me={me} onSave={onSave}/></section>
 </div>}function ProfileForm({me,onSave}){const[busy,setBusy]=useState(false);return <form className="portal-form" onSubmit={async e=>{e.preventDefault();setBusy(true);const f=Object.fromEntries(new FormData(e.currentTarget));await onSave(f);setBusy(false);}}><div className="form-row"><label>Full name<input name="fullName" defaultValue={me?.full_name} required/></label><label>Student email<input value={me?.email||""} disabled/><small>Email is used for sign in.</small></label></div><div className="form-row"><label>Department<input name="department" defaultValue={me?.department} required/></label><label>Academic year<select name="academicYear" defaultValue={me?.academic_year||"Year 1"}>{["Year 1","Year 2","Year 3","Year 4","Graduate","Other"].map(x=><option key={x}>{x}</option>)}</select></label></div><label>Student ID <small>Optional</small><input name="studentId" defaultValue={me?.student_id||""}/></label><label>Short bio<textarea name="bio" defaultValue={me?.bio||""} rows="4" maxLength={600}/></label><label className="check-row"><input type="checkbox" name="leaderboardOptOut" defaultChecked={Boolean(me?.leaderboard_opt_out)}/> Hide my profile from the student leaderboard</label><button className="primary-button" disabled={busy}>{busy?"Saving…":"Save profile"} <ArrowRight size={16}/></button></form>;}

function SettingsView(){const[busy,setBusy]=useState(false),[notice,setNotice]=useState(""),[error,setError]=useState("");return <div className="settings-grid"><div className="form-card"><div className="section-heading compact"><div><span className="eyebrow">ACCOUNT SECURITY</span><h2>Change password</h2><p>Confirm your current password before choosing a new one.</p></div></div><form className="portal-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError("");setNotice("");const form=e.currentTarget,values=Object.fromEntries(new FormData(form));if(values.newPassword!==values.confirmPassword){setError("New passwords do not match.");setBusy(false);return;}try{const result=await authClient.changePassword({currentPassword:values.currentPassword,newPassword:values.newPassword});if(result.error)throw new Error(result.error.message||"Password could not be changed.");form.reset();setNotice("Password changed successfully.");}catch(err){setError(err.message);}finally{setBusy(false);}}}><label>Current password<input name="currentPassword" type="password" autoComplete="current-password" required/></label><label>New password<input name="newPassword" type="password" minLength={10} autoComplete="new-password" required/><small>Use at least 10 characters.</small></label><label>Confirm new password<input name="confirmPassword" type="password" minLength={10} autoComplete="new-password" required/></label>{error&&<p className="error-text">{error}</p>}{notice&&<p className="success-text">{notice}</p>}<button className="primary-button" disabled={busy}>{busy?"Updating…":"Update password"} <ArrowRight size={16}/></button></form></div><div className="settings-note"><span className="settings-shield"><ShieldCheck size={22}/></span><h3>Your account, kept safe</h3><p>Neon Managed Better Auth secures password credentials and manages HTTP-only session cookies.</p><Link href="/forgot-password" className="text-link">Need help signing in? Reset your password</Link></div></div>;}

function AdminHome({data,me}){const s=data.stats||{};return <><div className="welcome-card admin-welcome"><div><span className="eyebrow">PLATFORM OVERVIEW</span><h2>Good to see you, {me.email}</h2><p>Here’s the latest from your SkillSwap community.</p></div><Link href="/admin/users?status=pending" className="primary-button">Review students <ArrowRight size={17}/></Link></div><div className="stat-grid admin-stats">{[[Users,s.total_students,"Total students"],[BookOpen,s.active_skills,"Active skills"],[ArrowLeftRight,s.total_swaps,"Swap requests"],[CheckCircle2,s.completed_exchanges,"Completed exchanges"],[Clock3,s.pending_requests,"Pending swaps"],[ShieldCheck,s.pending_accounts,"Awaiting review"]].map(([Icon,n,t])=><div className="stat-card" key={t}><span className="stat-icon"><Icon size={18}/></span><strong>{n||0}</strong><span>{t}</span></div>)}</div><div className="section-heading"><div><span className="eyebrow">ADMIN TOOLS</span><h2>Manage SkillSwap</h2></div></div><div className="admin-tool-grid">{[[Users,"Review registrations","Approve, reject, or suspend student accounts","/admin/users"],[BookOpen,"Skill listings","Inspect and moderate public listings","/admin/skills"],[Tags,"Skill categories","Keep discovery organized","/admin/categories"],[Activity,"Swap activity","Review requests across the platform","/admin/swaps"]].map(([Icon,t,c,url])=><Link href={url} key={t} className="admin-tool"><Icon size={19}/><b>{t}</b><p>{c}</p><ArrowRight size={15}/></Link>)}</div><div className="section-heading"><div><span className="eyebrow">NEXT UP</span><h2>Pending registrations</h2></div><Link href="/admin/users?status=pending" className="text-link">View all</Link></div><AdminUsers data={{users:data.pendingUsers||[]}} compact/> </>;}

function AdminUsers({data,onAction,onReset,compact=false}){const[query,setQuery]=useState("");const[status,setStatus]=useState(""),users=(data.users||[]).filter(u=>`${u.full_name} ${u.email} ${u.department}`.toLowerCase().includes(query.toLowerCase())&&(!status||u.account_status===status));return <><div className="filter-panel admin-filter"><label className="search-box"><Search size={17}/><input placeholder="Search students" value={query} onChange={e=>setQuery(e.target.value)}/></label>{!compact&&<label><span>Status</span><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">All states</option>{["pending","approved","rejected","suspended"].map(x=><option key={x}>{x}</option>)}</select></label>}</div>{users.length?<div className="data-list">{users.map(u=><article className="user-row" key={u.id}><div className="avatar">{initials(u.full_name)}</div><div className="user-main"><b>{u.full_name}</b><span>{u.email}</span><small>{u.department} · {u.academic_year}{u.student_id?` · ${u.student_id}`:""}{u.bio?` · ${u.bio}`:""}</small></div><Status value={u.account_status}/><div className="row-actions">{u.account_status==="pending"&&<><button className="primary-button small-button" onClick={()=>onAction?.(u.id,"approved")}>Approve</button><button className="secondary-button small-button" onClick={()=>window.confirm(`Reject ${u.full_name}'s application?`)&&onAction?.(u.id,"rejected")}>Reject</button></>}{u.account_status==="approved"&&<button className="secondary-button small-button" onClick={()=>window.confirm(`Suspend ${u.full_name}?`)&&onAction?.(u.id,"suspended")}>Suspend</button>}{u.account_status==="suspended"&&<button className="primary-button small-button" onClick={()=>onAction?.(u.id,"approved")}>Reactivate</button>}{!compact&&<button className="text-link" onClick={()=>onReset?.(u.id)}>Issue reset link</button>}</div></article>)}</div>:<Empty icon={Users} title="No matching students" copy="Try a different name, email, or account status."/>}</>;}

function AdminSkills({data,onAction}){return data.skills?.length?<div className="data-list">{data.skills.map(s=><article className="user-row" key={s.id}><span className="owned-icon"><BookOpen size={17}/></span><div className="user-main"><b>{s.name} <small>· {nice(s.skill_type)}</small></b><span>{s.full_name} · {s.email}</span><small>{s.category||"Other"} · {nice(s.level)}{s.description?` · ${s.description}`:""}</small></div><Status value={s.is_active?"active":"inactive"}/><button className="secondary-button small-button" onClick={()=>onAction(s.id,!s.is_active)}>{s.is_active?"Deactivate":"Reactivate"}</button></article>)}</div>:<Empty icon={BookOpen} title="No skill listings yet" copy="Student skill listings will appear here."/>;}
function Categories({data,error,busy,onRetry,onAdd,onUpdate,onDelete}){
 const [name,setName]=useState("");const [description,setDescription]=useState("");const [search,setSearch]=useState("");const [editing,setEditing]=useState(null);
 const categories=data.categories||[];const visible=categories.filter(c=>`${c.name} ${c.description||""}`.toLowerCase().includes(search.trim().toLowerCase()));
 async function createCategory(e){e.preventDefault();if(await onAdd({name:name.trim(),description:description.trim()})){setName("");setDescription("");}}
 async function saveCategory(e){e.preventDefault();if(await onUpdate(editing.id,{name:editing.name.trim(),description:editing.description.trim()}))setEditing(null);}
 async function removeCategory(category){if(!window.confirm(`Permanently delete “${category.name}”? This category has no linked skills.`))return;await onDelete(category.id);}
 return <div className="categories-page">
  <div className="page-intro categories-intro"><div><span className="eyebrow">ORGANIZE DISCOVERY</span><h2>Skill categories</h2><p>Keep skills easy to browse. Archived categories stay linked to their existing skills.</p></div><span className="result-count">{categories.length} {categories.length===1?"category":"categories"}</span></div>
  <section className="form-card category-add"><div><span className="eyebrow">NEW CATEGORY</span><h2>Add a category</h2><p>Give students a clear way to find related skills.</p></div><form onSubmit={createCategory}><label>Category name<input value={name} onChange={e=>setName(e.target.value)} maxLength={80} minLength={2} placeholder="e.g. Web Development" required/></label><label>Description <span className="muted-note">Optional</span><input value={description} onChange={e=>setDescription(e.target.value)} maxLength={500} placeholder="A short note about this category"/></label><button className="primary-button" disabled={busy||name.trim().length<2}><Plus size={16}/>{busy?"Adding…":"Add category"}</button></form></section>
  <div className="section-heading category-list-heading"><div><span className="eyebrow">MANAGE CATEGORIES</span><h2>All categories <span className="category-count">{categories.length}</span></h2></div><label className="search-box category-search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search categories" aria-label="Search categories"/></label></div>
  {error&&!categories.length?<div className="category-error" role="alert"><div><b>Categories could not be loaded</b><p>{error}</p></div><button className="secondary-button" onClick={onRetry} disabled={busy}>Retry</button></div>:null}
  {!error&&!categories.length?<Empty icon={Tags} title="No categories yet" copy="Add the first category above to organize student skills."/>:null}
  {!!categories.length&&!visible.length?<Empty icon={Search} title="No matching categories" copy="Try a different search term or clear your search."/>:null}
  <div className="category-grid">{visible.map(category=>editing?.id===category.id?<form className="category-card category-edit-card" key={category.id} onSubmit={saveCategory}><span className="owned-icon"><Tags size={18}/></span><label>Category name<input value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} minLength={2} maxLength={80} required/></label><label>Description<input value={editing.description} onChange={e=>setEditing({...editing,description:e.target.value})} maxLength={500}/></label><div className="category-actions"><button className="primary-button" disabled={busy||editing.name.trim().length<2}>{busy?"Saving…":"Save changes"}</button><button type="button" className="secondary-button" onClick={()=>setEditing(null)}>Cancel</button></div></form>:<article className={`category-card ${!category.is_active?"inactive":""}`} key={category.id}><div className="category-card-top"><span className="owned-icon"><Tags size={18}/></span><span className={`status-pill ${category.is_active?"approved":"archived"}`}>{category.is_active?"Active":"Archived"}</span></div><h3>{category.name}</h3><p className="category-description">{category.description||"No description provided."}</p><div className="category-meta"><b>{category.skills_count||0} {Number(category.skills_count)===1?"skill":"skills"}</b>{category.active_skills_count>0&&<span>{category.active_skills_count} active</span>}{category.created_at&&<time dateTime={category.created_at}>Added {new Date(category.created_at).toLocaleDateString()}</time>}</div><div className="category-actions"><button className="secondary-button" onClick={()=>setEditing({id:category.id,name:category.name,description:category.description||""})}>Edit</button><button className="secondary-button" disabled={busy} onClick={()=>onUpdate(category.id,{isActive:!category.is_active})}>{category.is_active?"Archive":"Restore"}</button>{Number(category.skills_count)===0&&<button className="category-delete" disabled={busy} onClick={()=>removeCategory(category)}>Delete</button>}</div></article>)}</div>
 </div>;
}
function AdminSwaps({data}){return data.swaps?.length?<div className="data-list">{data.swaps.map(s=><article className="admin-swap-row" key={s.id}><div className="user-main"><b>{s.sender_name} <ArrowRight size={13}/> {s.receiver_name}</b><span>{s.offered_skill} ⇄ {s.requested_skill}</span><small>{new Date(s.created_at).toLocaleString()}</small></div><Status value={s.status}/></article>)}</div>:<Empty icon={Activity} title="No requests to review" copy="Platform exchange activity will appear here."/>;}

function SkillModal({modal,onClose,onSubmit,data}){const [busy,setBusy]=useState(false);if(!modal)return null;const requestMode=modal.type==="request",editing=modal.type==="editSkill",skill=modal.skill||{};return <div className="modal-backdrop" onMouseDown={onClose}><motion.div className="modal-card" initial={{opacity:0,scale:.96,y:8}} animate={{opacity:1,scale:1,y:0}} onMouseDown={e=>e.stopPropagation()}><button className="icon-button modal-close" onClick={onClose}><X size={19}/></button><span className="eyebrow">{requestMode?"START A SKILL EXCHANGE":"YOUR SKILL PROFILE"}</span><h2>{requestMode?`Request ${skill.name}`:editing?`Edit ${skill.name}`:`${modal.skillType==="offered"?"Add a teaching skill":"Add a learning goal"}`}</h2><p>{requestMode?`Choose a skill you can offer to ${skill.full_name}.`:editing?"Update the details other students see.":"Tell your fellow students what you’d like to teach or learn."}</p><form className="portal-form" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await onSubmit(Object.fromEntries(new FormData(e.currentTarget)));}finally{setBusy(false);}}}>{requestMode?<><div className="swap-summary"><div><small>LEARNING</small><b>{skill.name}</b></div><ArrowLeftRight size={17}/><label><small>OFFERING</small><select name="offeredSkillId" required><option value="">Choose your skill</option>{data.mySkills?.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label></div><label>Personal message <textarea name="message" rows="3" maxLength={500} placeholder="What makes you interested in this exchange?"/></label></>:<><label>Skill name<input name="name" defaultValue={skill.name||""} minLength={2} maxLength={80} required placeholder="e.g. Intro to Python"/></label><label>Category<select name="categoryId" defaultValue={skill.category_id||""}><option value="">Choose a category</option>{data.categories?.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label><label>Proficiency<select name="level" defaultValue={skill.level||"beginner"}><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="expert">Expert</option></select></label><label>Description<textarea name="description" defaultValue={skill.description||""} maxLength={500} rows="3" placeholder="What can you help someone learn?"/></label><input type="hidden" name="skillType" value={modal.skillType}/></>}<button className="primary-button" disabled={busy}>{busy?"Saving…":requestMode?"Send swap request":editing?"Save changes":"Save skill"} <ArrowRight size={16}/></button></form></motion.div></div>;}
